//! FITS-WCS headers written for FrameSets whose pixel->sky Mapping holds no
//! WcsMap, against C's. fitschan.c `SplitMap` gives such a Mapping one: a
//! linear Mapping a CAR projection, with its longitude origin moved to the
//! pixel origin, and one giving constant celestial values the WcsMap of a
//! TAN header with those values at its reference point.
//!
//! `fitschan_splitmap_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/fitschan_splitmap_probe.c`.

#[rustfmt::skip]
#[path = "fitschan_splitmap_oracle/cases.rs"]
mod cases;

use ast_core::frames::{BasicFrameBuilder, CmpFrame, DynFrame, FrameRef, FrameSet, SkyFrame};
use ast_core::mappings::{CmpMap, Composition, DynMapping, MatrixMap, PermMap, ShiftMap};
use ast_core::{AnyObject, Channel, Encoding, FitsChan};

fn sky() -> DynFrame {
    let mut f = SkyFrame::new(ast_core::frames::SkySystem::Icrs);
    f.clear_system();
    Box::new(f)
}

fn linear(diag: &[f64], shift: &[f64]) -> DynMapping {
    let n = diag.len();
    let mut m = ndarray::Array2::<f64>::zeros((n, n));
    for (i, d) in diag.iter().enumerate() {
        m[[i, i]] = *d;
    }
    Box::new(
        CmpMap::new(
            Box::new(MatrixMap::new(m).unwrap()),
            Box::new(ShiftMap::new(shift.to_vec())),
            Composition::Series,
        )
        .unwrap(),
    )
}

/// The probe's current Frame and pixel->WCS Mapping for `name`.
fn case(name: &str) -> (DynFrame, DynMapping) {
    match name {
        "linear" => (sky(), linear(&[-0.001, 0.002], &[0.2, 0.3])),
        "linear_3d" => (
            Box::new(CmpFrame::new(
                sky(),
                Box::new(BasicFrameBuilder::new(1).domain("X").build().unwrap()),
            )),
            linear(&[-0.001, 0.002, 3.0], &[0.2, 0.3, 4.0]),
        ),
        "constant" => (
            sky(),
            Box::new(PermMap::new(&[0, 0], &[-1, -2], &[0.5, -0.25]).unwrap()),
        ),
        other => panic!("no case {other}"),
    }
}

#[test]
fn headers_match_c() {
    for &(name, ret, want) in cases::CASES {
        let (frame, map) = case(name);
        let naxes = map.nin();
        let mut fs = FrameSet::new(Box::new(
            BasicFrameBuilder::new(naxes)
                .domain("GRID")
                .build()
                .unwrap(),
        ));
        fs.add_frame(FrameRef::Base, map, frame).unwrap();
        let mut fc = FitsChan::new();
        fc.set_encoding(Encoding::FitsWcs);
        let written = fc.write(&AnyObject::FrameSet(fs)).unwrap();
        assert_eq!(written as i32, ret, "{name}: value written");
        fc.clear_card().unwrap();
        let mut cards = Vec::new();
        while let Some(card) = fc.find_fits("%f", true).unwrap() {
            cards.push(card);
        }
        assert_eq!(cards, want, "{name}");
    }
}
